pub enum SendMode {
    Code,
    /// The code and the spec together.
    Both,
    Spec,
    /// A question, which edits neither the code nor the spec.
    Ask,
    /// The prompt passed to the agent just as it is written: no system
    /// prompt, hidden anchor, spec build, or slices.
    Freeform,
}

